16	func uploadObject(t *testing.T, h http.Handler, body []byte) objectResponse {
17		t.Helper()
18		rec := postBody(t, h, body, "application/octet-stream")
19		if rec.Code != http.StatusCreated && rec.Code != http.StatusOK {
20			t.Fatalf("upload status = %d, body = %s", rec.Code, rec.Body.String())
21		}
22		return decodeObjectResponse(t, rec)
23	}
