25	func putPinRaw(t *testing.T, h http.Handler, cid string, body string, contentType string) *httptest.ResponseRecorder {
26		t.Helper()
27		var rdr *bytes.Reader
28		if body == "" {
29			rdr = bytes.NewReader(nil)
30		} else {
31			rdr = bytes.NewReader([]byte(body))
32		}
33		req := httptest.NewRequest(http.MethodPut, "/v1/pins/"+cid, rdr)
34		if contentType != "" {
35			req.Header.Set("Content-Type", contentType)
36		}
37		rec := httptest.NewRecorder()
38		h.ServeHTTP(rec, req)
39		return rec
40	}
41	
42	func decodePin(t *testing.T, rec *httptest.ResponseRecorder) pinResponse {
43		t.Helper()
44		var resp pinResponse
45		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
46			t.Fatalf("pin response is not JSON: %v (body=%s)", err, rec.Body.String())
47		}
48		return resp
49	}
