51	func listPins(t *testing.T, h http.Handler) []pinResponse {
52		t.Helper()
53		rec := httptest.NewRecorder()
54		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/v1/pins", nil))
55		if rec.Code != http.StatusOK {
56			t.Fatalf("list pins status = %d", rec.Code)
57		}
58		var resp pinListResponse
59		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
60			t.Fatalf("list pins is not JSON: %v", err)
61		}
62		return resp.Pins
63	}
