65	func runGC(t *testing.T, h http.Handler, dryRun string) gcResponse {
66		t.Helper()
67		url := "/v1/gc"
68		if dryRun != "" {
69			url += "?dryRun=" + dryRun
70		}
71		rec := httptest.NewRecorder()
72		h.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, url, nil))
73		if rec.Code != http.StatusOK {
74			t.Fatalf("gc status = %d, body = %s", rec.Code, rec.Body.String())
75		}
76		var resp gcResponse
77		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
78			t.Fatalf("gc response is not JSON: %v", err)
