83	func TestPinCreateUpdateDeleteLifecycle(t *testing.T) {
84		h := Handler()
85		obj := uploadObject(t, h, []byte("pinned content"))
86	
87		// First pin: 201, permanent.
88		rec := putPinRaw(t, h, obj.CID, `{}`, "application/json")
89		if rec.Code != http.StatusCreated {
90			t.Fatalf("create pin status = %d, want %d (body=%s)", rec.Code, http.StatusCreated, rec.Body.String())
91		}
92		pin := decodePin(t, rec)
93		if pin.CID != obj.CID || pin.ExpiresAt != nil {
94			t.Fatalf("unexpected create response: %+v", pin)
95		}
96	
97		// Second effective pin: 200.
98		future := time.Now().Add(time.Hour).UTC().Format(time.RFC3339)
99		rec = putPinRaw(t, h, obj.CID, fmt.Sprintf(`{"expiresAt":%q}`, future), "application/json")
100		if rec.Code != http.StatusOK {
101			t.Fatalf("update pin status = %d, want %d", rec.Code, http.StatusOK)
102		}
103		pin = decodePin(t, rec)
104		if pin.CID != obj.CID || pin.ExpiresAt == nil {
105			t.Fatalf("unexpected update response: %+v", pin)
106		}
107	
108		// Back to permanent: still 200.
109		rec = putPinRaw(t, h, obj.CID, `{"expiresAt":null}`, "application/json")
110		if rec.Code != http.StatusOK {
111			t.Fatalf("reset pin status = %d, want %d", rec.Code, http.StatusOK)
112		}
113		if decodePin(t, rec).ExpiresAt != nil {
114			t.Fatal("expiresAt should be null for permanent pin")
115		}
116	
117		pins := listPins(t, h)
118		if len(pins) != 1 || pins[0].CID != obj.CID || pins[0].ExpiresAt != nil {
119			t.Fatalf("unexpected pin list: %+v", pins)
120		}
121	
122		// Delete: 204, then 404.
123		delRec := httptest.NewRecorder()
124		h.ServeHTTP(delRec, httptest.NewRequest(http.MethodDelete, "/v1/pins/"+obj.CID, nil))
125		if delRec.Code != http.StatusNoContent {
126			t.Fatalf("delete pin status = %d, want %d", delRec.Code, http.StatusNoContent)
127		}
128		if delRec.Body.Len() != 0 {
129			t.Fatalf("204 response must have no body, got %q", delRec.Body.String())
130		}
131		delRec = httptest.NewRecorder()
132		h.ServeHTTP(delRec, httptest.NewRequest(http.MethodDelete, "/v1/pins/"+obj.CID, nil))
133		if delRec.Code != http.StatusNotFound {
134			t.Fatalf("second delete status = %d, want %d", delRec.Code, http.StatusNotFound)
135		}
136		assertErrorCode(t, delRec, "pin_not_found")
137	
138		if pins := listPins(t, h); len(pins) != 0 {
139			t.Fatalf("pin list should be empty, got %+v", pins)
140		}
141	
142		// Deleting the pin does not delete the object.
143		getRec := httptest.NewRecorder()
144		h.ServeHTTP(getRec, httptest.NewRequest(http.MethodGet, "/v1/objects/"+obj.CID, nil))
145		if getRec.Code != http.StatusOK {
146			t.Fatalf("object should survive pin removal, got %d", getRec.Code)
147		}
148	}
