150	func TestPinMissingObjectAndBadCID(t *testing.T) {
151		h := Handler()
152		missing := "sha256:" + strings.Repeat("0", 64)
153	
154		rec := putPinRaw(t, h, missing, `{}`, "application/json")
155		if rec.Code != http.StatusNotFound {
156			t.Fatalf("pin missing object status = %d, want %d", rec.Code, http.StatusNotFound)
157		}
158		assertErrorCode(t, rec, "object_not_found")
159	
160		for _, bad := range []string{"not-a-cid", "sha256:ABC", "sha256:" + strings.Repeat("g", 64)} {
161			rec := putPinRaw(t, h, bad, `{}`, "application/json")
162			if rec.Code != http.StatusBadRequest {
163				t.Fatalf("pin bad cid %q status = %d, want %d", bad, rec.Code, http.StatusBadRequest)
164			}
165			assertErrorCode(t, rec, "invalid_cid")
166	
167			delRec := httptest.NewRecorder()
168			h.ServeHTTP(delRec, httptest.NewRequest(http.MethodDelete, "/v1/pins/"+bad, nil))
169			if delRec.Code != http.StatusBadRequest {
170				t.Fatalf("delete bad cid %q status = %d, want %d", bad, delRec.Code, http.StatusBadRequest)
171			}
172			assertErrorCode(t, delRec, "invalid_cid")
173		}
174	
175		// Valid shape but no pin exists: pin_not_found, not object_not_found.
176		delRec := httptest.NewRecorder()
177		h.ServeHTTP(delRec, httptest.NewRequest(http.MethodDelete, "/v1/pins/"+missing, nil))
178		if delRec.Code != http.StatusNotFound {
179			t.Fatalf("delete missing pin status = %d, want %d", delRec.Code, http.StatusNotFound)
180		}
181		assertErrorCode(t, delRec, "pin_not_found")
182	}
