59	// chunkCID returns the identifier for one chunk's raw bytes.
60	func chunkCID(data []byte) string {
61		sum := sha256.Sum256(data)
62		return cidPrefix + hex.EncodeToString(sum[:])
63	}
64	
65	// rootCID derives the object identifier from the deterministic manifest: the
66	// total object length followed by the ordered chunk identifiers, encoded as
67	// "size:<N>\n" then one "<cid>\n" line per chunk.
68	func rootCID(size int, cids []string) string {
69		var b strings.Builder
70		fmt.Fprintf(&b, "size:%d\n", size)
71		for _, c := range cids {
72			b.WriteString(c)
73			b.WriteByte('\n')
74		}
75		sum := sha256.Sum256([]byte(b.String()))
76		return cidPrefix + hex.EncodeToString(sum[:])
77	}
78	
79	// put stores the object, or returns the existing one when the same root
80	// identifier is already present. Exactly one concurrent caller observes
81	// created == true for a given object.
82	func (s *store) put(obj *object) (stored *object, created bool) {
83		s.mu.Lock()
84		defer s.mu.Unlock()
85		if existing, ok := s.objects[obj.cid]; ok {
86			return existing, false
87		}
88		s.objects[obj.cid] = obj
89		return obj, true
90	}
