100	func validCID(s string) bool {
101		if len(s) != len(cidPrefix)+64 || !strings.HasPrefix(s, cidPrefix) {
102			return false
103		}
104		for _, c := range s[len(cidPrefix):] {
105			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
106				return false
107			}
108		}
109		return true
110	}
