119	// does not exist; updated is true only when an already valid pin was
120	// replaced. Expiration and object existence are decided together under the
121	// store lock, so a concurrent garbage collection cannot delete an object
122	// whose pin succeeds in the same acceptance order.
123	func (s *store) upsertPin(cid string, expiresAt *time.Time, now time.Time) (updated, ok bool) {
124		s.mu.Lock()
125		defer s.mu.Unlock()
126		if _, exists := s.objects[cid]; !exists {
127			return false, false
128		}
129		if existing, pinned := s.pins[cid]; pinned && existing.validAt(now) {
130			updated = true
131		}
132		s.pins[cid] = &pin{cid: cid, expiresAt: expiresAt}
