149	// listPins returns all currently valid pins ordered by cid.
150	func (s *store) listPins(now time.Time) []pinInfo {
151		s.mu.RLock()
152		defer s.mu.RUnlock()
153		var out []pinInfo
154		for _, p := range s.pins {
155			if !p.validAt(now) {
156				continue
157			}
158			out = append(out, pinInfo{cid: p.cid, expiresAt: p.expiresAt})
